package io.tornado.notification;
import io.tornado.persistence.*;import org.springframework.stereotype.Component;import java.math.*;import java.time.*;import java.time.format.*;import java.util.*;
@Component public class TelegramMessageFormatter{private static final ZoneId TEHRAN=ZoneId.of("Asia/Tehran");private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss 'Tehran'");private String price(BigDecimal p){return p==null?"legacy / unavailable":String.format(Locale.US,"%,.4f",p);}private String pct(BigDecimal p){return p==null?"?":p.stripTrailingZeros().toPlainString();}private String horizon(long s){return s<3600?s/60+"m":s<86400?s/3600+"h":"24h";}private String mark(Instant at){return at==null?"⬜":"✅";}
 public String open(MixTradeSimulation s){return render(s,List.of());}public String update(MixTradeSimulation s,List<MixTradeSimulation.Milestone>events){return render(s,events);}public String closed(MixTradeSimulation s){return render(s,List.of());}
 private String render(MixTradeSimulation s,List<MixTradeSimulation.Milestone>events){String side=s.getDirection()==Direction.UP?"🟢 Direction: LONG":"🔴 Direction: SHORT";String banner=events.isEmpty()?"":events.stream().map(Enum::name).collect(java.util.stream.Collectors.joining(" + "))+" reached\n\n";String status=s.getStatus()==MixTradeSimulation.Status.OPEN?"⏳ OPEN":s.getStatus()==MixTradeSimulation.Status.TP3_HIT?"✅ TP3 HIT":s.getStatus()==MixTradeSimulation.Status.SL3_HIT?"❌ SL3 HIT":s.getStatus().name();return banner+"🚨 TORNIDO SIGNAL\n\n🪙 Coin: "+s.getCoin().getSymbol()+"/USDT\n"+side+"\n⏱ Horizon: "+horizon(s.getHorizonSeconds())+"\n\n🏆 Best Mix: #"+s.getMixRank()+"\n🧠 Methods:\n"+String.join(" + ",s.getMethodNames())+"\n\n🗳 Agreement: "+s.getAgreementCount()+" / "+s.getTotalMethods()+" "+(s.getDirection()==Direction.UP?"LONG":"SHORT")+"\n\n💰 Entry: "+price(s.getEntryPrice())+" USDT\n\n🎯 TAKE PROFITS\n"+line(mark(s.getTp1HitAt()),"TP1",s.getTp1Price(),s.getTp1Percent(),s.getTp1HitAt())+line(mark(s.getTp2HitAt()),"TP2",s.getTp2Price(),s.getTp2Percent(),s.getTp2HitAt())+line(mark(s.getTp3HitAt()),"TP3",s.getTp3Price(),s.getTp3Percent(),s.getTp3HitAt())+"\n🛑 STOP LOSSES\n"+line(mark(s.getSl1HitAt()),"SL1",s.getSl1Price(),s.getSl1Percent(),s.getSl1HitAt())+line(mark(s.getSl2HitAt()),"SL2",s.getSl2Price(),s.getSl2Percent(),s.getSl2HitAt())+line(mark(s.getSl3HitAt()),"SL3",s.getSl3Price(),s.getSl3Percent(),s.getSl3HitAt())+"\n📊 Historical Trades: "+s.getHistoricalSamples()+"\n✅ Target Hit Rate: "+String.format("%.1f%%",s.getHistoricalTargetHitRate())+"\n📈 Directional Accuracy: "+String.format("%.1f%%",s.getHistoricalDirectionalAccuracy())+"\n📐 Wilson Score: "+String.format("%.1f%%",s.getHistoricalWilsonScore())+"\n\n🕒 Opened: "+TIME.format(s.getOpenedAt().atZone(TEHRAN))+"\n📌 Simulation ID: #"+s.getId()+"\n\nStatus: "+status+(s.getResultPercent()==null?"":"\nResult: "+String.format("%+.3f%%",s.getResultPercent()));}
 private String line(String mark,String label,BigDecimal price,BigDecimal percent,Instant hit){return mark+" "+label+": "+price(price)+" ("+(label.startsWith("TP")?"+":"-")+pct(percent)+"%)"+(hit==null?"":" · "+TIME.format(hit.atZone(TEHRAN)))+"\n";}
}
